import { z } from "zod";
import {
  CurrencySchema,
  DataLabelSchema,
  IdSchema,
  IsoDateTimeSchema,
} from "./primitives";

/**
 * A tradable instrument in the candidate universe. Sourced read-only from
 * eToro or a fixture — never an order-capable handle.
 */
export const InstrumentSchema = z.object({
  id: IdSchema,
  symbol: z.string().min(1),
  name: z.string().min(1),
  sector: z.string().min(1),
  assetClass: z.enum(["equity", "etf", "crypto", "commodity", "index"]),
  currency: CurrencySchema,
});
export type Instrument = z.infer<typeof InstrumentSchema>;

export const PricePointSchema = z.object({
  t: IsoDateTimeSchema,
  close: z.number().nonnegative(),
});
export type PricePoint = z.infer<typeof PricePointSchema>;

/** A per-instrument close-price series with explicit provenance. */
export const PriceHistorySchema = z.object({
  instrumentId: IdSchema,
  currency: CurrencySchema,
  source: z.enum(["etoro", "fixture"]),
  label: DataLabelSchema,
  asOf: IsoDateTimeSchema,
  points: z.array(PricePointSchema).min(1),
});
export type PriceHistory = z.infer<typeof PriceHistorySchema>;

export const InstrumentQuoteSchema = z.object({
  instrumentId: IdSchema,
  price: z.number().nonnegative(),
  currency: CurrencySchema,
});
export type InstrumentQuote = z.infer<typeof InstrumentQuoteSchema>;

/** A point-in-time snapshot of quotes for the universe. */
export const MarketSnapshotSchema = z.object({
  asOf: IsoDateTimeSchema,
  source: z.enum(["etoro", "fixture"]),
  label: DataLabelSchema,
  quotes: z.array(InstrumentQuoteSchema),
});
export type MarketSnapshot = z.infer<typeof MarketSnapshotSchema>;

import { z } from "zod";
import { RiskBreachCodeSchema } from "./mandate";
import {
  CurrencySchema,
  DataLabelSchema,
  IdSchema,
  IsoDateTimeSchema,
  MoneySchema,
  RatioSchema,
} from "./primitives";

export const TradeSideSchema = z.enum(["buy", "sell"]);
export type TradeSide = z.infer<typeof TradeSideSchema>;

/** A held position. The MVP baseline holds none of these (all cash). */
export const PositionSchema = z.object({
  instrumentId: IdSchema,
  quantity: z.number(),
  avgPrice: MoneySchema,
  marketValue: MoneySchema,
  /** Fraction of NAV. */
  weight: RatioSchema,
});
export type Position = z.infer<typeof PositionSchema>;

/**
 * A point-in-time paper-portfolio snapshot. MVP starts at `cash = €1,000` with
 * an empty `positions` array and `nav == cash`.
 */
export const PortfolioSnapshotSchema = z.object({
  id: IdSchema,
  asOf: IsoDateTimeSchema,
  baseCurrency: CurrencySchema,
  cash: MoneySchema,
  nav: MoneySchema,
  positions: z.array(PositionSchema),
  label: DataLabelSchema,
});
export type PortfolioSnapshot = z.infer<typeof PortfolioSnapshotSchema>;

/**
 * An allocation intent from the Portfolio Manager. It expresses a target, not a
 * broker order — the deterministic risk engine turns it into a pass/resize/
 * reject result, and only an approved result mutates the paper ledger.
 */
export const ProposedActionSchema = z.object({
  id: IdSchema,
  instrumentId: IdSchema,
  side: TradeSideSchema,
  /** Target weight of NAV after the action. */
  targetWeight: RatioSchema,
  /** Intended notional for the action. */
  amount: MoneySchema,
  /** Evidence backing this specific action. */
  evidenceIds: z.array(IdSchema).default([]),
});
export type ProposedAction = z.infer<typeof ProposedActionSchema>;

export const RiskResultSchema = z.enum(["pass", "resize", "reject"]);
export type RiskResult = z.infer<typeof RiskResultSchema>;

/**
 * The deterministic verdict on one proposed action. `numbers` carries the
 * reproducible figures behind the decision so the Risk Officer can explain a
 * block with exact values. `breachCode` is set on a resize or reject.
 */
export const RiskCheckSchema = z.object({
  id: IdSchema,
  actionId: IdSchema,
  result: RiskResultSchema,
  breachCode: RiskBreachCodeSchema.optional(),
  detail: z.string().min(1),
  numbers: z.record(z.string(), z.number()).default({}),
  /** Present when the engine resized rather than rejected. */
  resizedAmount: MoneySchema.optional(),
});
export type RiskCheck = z.infer<typeof RiskCheckSchema>;

/**
 * An action the paper ledger actually applies after human approval. Produced by
 * deterministic Trader code — never by an agent and never by a broker client.
 */
export const PaperOrderSchema = z.object({
  id: IdSchema,
  actionId: IdSchema,
  instrumentId: IdSchema,
  side: TradeSideSchema,
  quantity: z.number().nonnegative(),
  price: MoneySchema,
  notional: MoneySchema,
  appliedAt: IsoDateTimeSchema,
});
export type PaperOrder = z.infer<typeof PaperOrderSchema>;

/** Per-instrument weight delta between two portfolios. */
export const WeightDeltaSchema = z.object({
  instrumentId: IdSchema,
  currentWeight: RatioSchema,
  proposedWeight: RatioSchema,
});
export type WeightDelta = z.infer<typeof WeightDeltaSchema>;

/**
 * Current-versus-proposed comparison. For the MVP this compares the all-cash
 * baseline against the proposed allocation and its retained cash.
 */
export const PortfolioComparisonSchema = z.object({
  currentNav: MoneySchema,
  proposedInvested: MoneySchema,
  proposedCash: MoneySchema,
  deltas: z.array(WeightDeltaSchema),
});
export type PortfolioComparison = z.infer<typeof PortfolioComparisonSchema>;

import { z } from "zod";
import { DataLabelSchema, IdSchema, IsoDateTimeSchema } from "./primitives";

/**
 * A material event or change that enters the committee run. Prepared as
 * historical or synthetic for the demo; always labeled.
 */
export const MaterialEventSchema = z.object({
  id: IdSchema,
  headline: z.string().min(1),
  summary: z.string().min(1),
  occurredAt: IsoDateTimeSchema,
  label: DataLabelSchema,
  evidenceIds: z.array(IdSchema).default([]),
});
export type MaterialEvent = z.infer<typeof MaterialEventSchema>;

/**
 * A human-readable trace entry for the Saloon. Only emitted when an observable
 * event occurs — never filler. Each material entry links to evidence, a graph
 * edge, or a record so the UI never has to parse prose to discover state.
 */
export const ActivityKindSchema = z.enum([
  "phase_changed",
  "source_read",
  "relationship_added",
  "claim_created",
  "contradiction_found",
  "risk_changed_action",
  "recommendation_made",
  "paper_trade",
  "note",
]);
export type ActivityKind = z.infer<typeof ActivityKindSchema>;

export const ActivityEventSchema = z.object({
  id: IdSchema,
  /** The committee stage that produced this activity, if any. */
  stage: z.string().optional(),
  kind: ActivityKindSchema,
  message: z.string().min(1),
  at: IsoDateTimeSchema,
  /** Optional links to the record this activity refers to. */
  evidenceIds: z.array(IdSchema).default([]),
  refId: IdSchema.optional(),
});
export type ActivityEvent = z.infer<typeof ActivityEventSchema>;

import { z } from "zod";
import { ClaimSchema } from "./evidence";
import { RiskBreachCodeSchema } from "./mandate";
import {
  PortfolioComparisonSchema,
  ProposedActionSchema,
  RiskCheckSchema,
} from "./portfolio";
import {
  IdSchema,
  IsoDateTimeSchema,
  MoneySchema,
  RatioSchema,
} from "./primitives";

/** The committee stages, in the order the orchestrator runs them. */
export const AGENT_STAGES = [
  "fundamental_analyst",
  "market_context",
  "risk_officer",
  "portfolio_manager",
  "bear_critic",
  "report_writer",
] as const;

export const AgentStageSchema = z.enum(AGENT_STAGES);
export type AgentStage = z.infer<typeof AgentStageSchema>;

export const StageStatusSchema = z.enum([
  "pending",
  "running",
  "complete",
  "skipped",
  "failed",
  "blocked",
]);
export type StageStatus = z.infer<typeof StageStatusSchema>;

/**
 * Bookkeeping for one committee stage. Timing and status live here; the payload
 * lives in the matching typed field on the committee state, linked by
 * `outputId`. Failed and skipped stages remain visible in the receipt.
 */
export const StageRecordSchema = z.object({
  runId: IdSchema,
  stage: AgentStageSchema,
  status: StageStatusSchema,
  startedAt: IsoDateTimeSchema.nullable(),
  completedAt: IsoDateTimeSchema.nullable(),
  /** The id of the produced output, or null if the stage produced none. */
  outputId: IdSchema.nullable(),
  /** Human-readable reason for a skip/failure/block, when relevant. */
  note: z.string().optional(),
});
export type StageRecord = z.infer<typeof StageRecordSchema>;

// ── Per-stage outputs ───────────────────────────────────────────────────────

/** Fundamental Analyst output for one instrument, from an isolated evidence pack. */
export const FundamentalReportSchema = z.object({
  id: IdSchema,
  instrumentId: IdSchema,
  quality: z.string().min(1),
  valuation: z.string().min(1),
  financialStrength: z.string().min(1),
  catalysts: z.array(z.string()).default([]),
  risks: z.array(z.string()).default([]),
  claims: z.array(ClaimSchema).default([]),
});
export type FundamentalReport = z.infer<typeof FundamentalReportSchema>;

/** Market Context Analyst output, from an isolated context pack. */
export const MarketContextReportSchema = z.object({
  id: IdSchema,
  summary: z.string().min(1),
  drivers: z.array(z.string()).default([]),
  sectorView: z.string().min(1),
  macroView: z.string().min(1),
  claims: z.array(ClaimSchema).default([]),
});
export type MarketContextReport = z.infer<typeof MarketContextReportSchema>;

export const RiskMetricsSchema = z.object({
  volatility: z.number().nonnegative(),
  beta: z.number(),
  concentration: RatioSchema,
  /** Exposure by sector name, each a fraction of NAV. */
  sectorExposure: z.record(z.string(), RatioSchema),
});
export type RiskMetrics = z.infer<typeof RiskMetricsSchema>;

export const StressResultSchema = z.object({
  scenario: z.string().min(1),
  navImpact: MoneySchema,
  navImpactPct: z.number(),
});
export type StressResult = z.infer<typeof StressResultSchema>;

/**
 * Risk Officer output. Deterministic: metrics, stress, per-action checks, and
 * the current-vs-proposed comparison all come from the pure risk engine.
 */
export const RiskReportSchema = z.object({
  id: IdSchema,
  metrics: RiskMetricsSchema,
  stress: z.array(StressResultSchema).default([]),
  checks: z.array(RiskCheckSchema),
  comparison: PortfolioComparisonSchema,
  /** Hard blocks raised; a non-empty list forces the run to `blocked`. */
  hardBlocks: z.array(RiskBreachCodeSchema).default([]),
});
export type RiskReport = z.infer<typeof RiskReportSchema>;

/**
 * Portfolio Manager recommendation (proposal or revision). Carries structured
 * bull / context / bear evidence and the conditions that would invalidate it.
 */
export const RecommendationSchema = z.object({
  id: IdSchema,
  /** Which revision this is: 0 = initial proposal, 1 = post-critique revision. */
  revision: z.number().int().nonnegative().default(0),
  actions: z.array(ProposedActionSchema),
  bull: z.array(ClaimSchema).default([]),
  context: z.array(ClaimSchema).default([]),
  bear: z.array(ClaimSchema).default([]),
  confidence: RatioSchema,
  invalidationConditions: z.array(z.string()).default([]),
  expectedCashAfter: MoneySchema,
});
export type Recommendation = z.infer<typeof RecommendationSchema>;

/** Bear/Critic output. Flags weaknesses and failure scenarios; cannot veto. */
export const BearCaseSchema = z.object({
  id: IdSchema,
  targetRecommendationId: IdSchema,
  weaknesses: z.array(z.string()).default([]),
  failureScenarios: z.array(z.string()).default([]),
  claims: z.array(ClaimSchema).default([]),
});
export type BearCase = z.infer<typeof BearCaseSchema>;

/**
 * Communications/Report Writer output. Runs only after the human decision and
 * cannot influence allocation.
 */
export const CommitteeReportSchema = z.object({
  id: IdSchema,
  narrative: z.string().min(1),
  decisionSummary: z.string().min(1),
  disclaimers: z.array(z.string()).default([]),
});
export type CommitteeReport = z.infer<typeof CommitteeReportSchema>;

import { z } from "zod";
import {
  BearCaseSchema,
  CommitteeReportSchema,
  RecommendationSchema,
  RiskReportSchema,
} from "./agents";
import { EvidenceSchema } from "./evidence";
import { MaterialEventSchema } from "./events";
import {
  PaperOrderSchema,
  PortfolioSnapshotSchema,
} from "./portfolio";
import { IdSchema, IsoDateTimeSchema } from "./primitives";

/**
 * The human's explicit decision. Required before any paper-ledger mutation —
 * the orchestrator refuses to apply actions without an `approved` decision.
 */
export const UserDecisionSchema = z.object({
  decision: z.enum(["approved", "rejected"]),
  decidedAt: IsoDateTimeSchema,
  decidedBy: z.string().optional(),
  note: z.string().optional(),
});
export type UserDecision = z.infer<typeof UserDecisionSchema>;

/**
 * The inspectable artifact of one committee run. Contains the event, the
 * relationship evidence, the risk comparison (including the rejected/resized
 * alternative), the human approval, the applied paper actions, and the report.
 */
export const DecisionReceiptSchema = z.object({
  id: IdSchema,
  runId: IdSchema,
  createdAt: IsoDateTimeSchema,
  event: MaterialEventSchema.nullable(),
  portfolioBefore: PortfolioSnapshotSchema,
  portfolioAfter: PortfolioSnapshotSchema,
  recommendation: RecommendationSchema,
  riskReport: RiskReportSchema,
  bearCase: BearCaseSchema.nullable(),
  userDecision: UserDecisionSchema,
  appliedOrders: z.array(PaperOrderSchema),
  report: CommitteeReportSchema.nullable(),
  /** Every evidence record referenced anywhere in this receipt. */
  evidence: z.array(EvidenceSchema),
});
export type DecisionReceipt = z.infer<typeof DecisionReceiptSchema>;

import { z } from "zod";
import {
  BearCaseSchema,
  CommitteeReportSchema,
  FundamentalReportSchema,
  MarketContextReportSchema,
  RecommendationSchema,
  RiskReportSchema,
  StageRecordSchema,
} from "./agents";
import { EvidenceSchema, RelationshipGraphSchema } from "./evidence";
import { ActivityEventSchema, MaterialEventSchema } from "./events";
import { MandateSchema } from "./mandate";
import { InstrumentSchema, MarketSnapshotSchema } from "./market-data";
import { FundPhaseSchema } from "./phases";
import {
  PaperOrderSchema,
  PortfolioSnapshotSchema,
  ProposedActionSchema,
  RiskCheckSchema,
} from "./portfolio";
import { DecisionReceiptSchema, UserDecisionSchema } from "./receipts";
import { IdSchema, IsoDateTimeSchema } from "./primitives";

/** Run-level metadata for one committee execution. */
export const RunSchema = z.object({
  id: IdSchema,
  scenarioId: IdSchema,
  startedAt: IsoDateTimeSchema,
  completedAt: IsoDateTimeSchema.nullable(),
  /** Whether this run is a live analysis, a historical replay, or synthetic. */
  label: z.enum(["live", "historical", "synthetic"]),
});
export type Run = z.infer<typeof RunSchema>;

/**
 * The single object enriched by each committee stage. Not prose passed from
 * prompt to prompt — one typed record that every stage reads from and writes to.
 * Deterministic analytics stay separate from model interpretation.
 *
 * This is the same shape sent to the browser (see {@link AnalysisSchema}): it
 * models records only — never prompts, credentials, or hidden chain-of-thought,
 * which live in the server layer and are never represented here.
 */
export const InvestmentCommitteeStateSchema = z.object({
  run: RunSchema,
  /** The current fund phase; the UI derives everything visual from this. */
  phase: FundPhaseSchema,

  // Inputs
  mandate: MandateSchema,
  candidateUniverse: z.array(InstrumentSchema),
  portfolioSnapshot: PortfolioSnapshotSchema,
  materialEvents: z.array(MaterialEventSchema).default([]),
  marketSnapshot: MarketSnapshotSchema.nullable(),

  // Sourced evidence + relationship graph
  evidence: z.array(EvidenceSchema).default([]),
  graph: RelationshipGraphSchema,

  // Stage bookkeeping (status + timing for every stage, including skipped/failed)
  stages: z.array(StageRecordSchema).default([]),

  // Stage outputs
  fundamentalReports: z.array(FundamentalReportSchema).default([]),
  marketContext: MarketContextReportSchema.nullable(),
  riskReport: RiskReportSchema.nullable(),
  finalRecommendation: RecommendationSchema.nullable(),
  bearCase: BearCaseSchema.nullable(),

  // Flattened views for the UI (derived from the outputs above)
  proposedActions: z.array(ProposedActionSchema).default([]),
  riskChecks: z.array(RiskCheckSchema).default([]),

  // Decision + application
  userDecision: UserDecisionSchema.nullable(),
  appliedOrders: z.array(PaperOrderSchema).default([]),
  portfolioAfter: PortfolioSnapshotSchema.nullable(),
  report: CommitteeReportSchema.nullable(),

  // Trace + final artifact
  activities: z.array(ActivityEventSchema).default([]),
  receipt: DecisionReceiptSchema.nullable(),
});
export type InvestmentCommitteeState = z.infer<
  typeof InvestmentCommitteeStateSchema
>;

/**
 * The browser-facing analysis contract. Identical to the committee state for
 * the MVP — the state already models records only. Kept as a distinct name so a
 * future server-side projection has a place to narrow.
 */
export const AnalysisSchema = InvestmentCommitteeStateSchema;
export type Analysis = InvestmentCommitteeState;

